+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<MessageHistory.Message> grid = new Grid<>();
+    private final MessageHistory history;
+
+    public ContactView(MessageHistory history) {
+        this.history = history;
+        setMaxWidth("64rem");
+        name.setManualValidation(true);
+        email.setManualValidation(true);
+        phone.setManualValidation(true);
+        message.setManualValidation(true);
+        // Eager updates also cover edits made immediately before navigation or Enter.
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        name.addValueChangeListener(event -> send.setEnabled(true));
+        email.addValueChangeListener(event -> send.setEnabled(true));
+        phone.addValueChangeListener(event -> send.setEnabled(true));
+        message.addValueChangeListener(event -> send.setEnabled(true));
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        FormLayout form = new FormLayout();
+        form.setWidthFull();
+        form.setMaxWidth("40rem");
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("32rem", 2));
+        form.add(name, 2);
+        form.add(email, phone);
+        form.add(message, 2);
+        message.setMinHeight("9rem");
+
+        grid.addColumn(MessageHistory.Message::name).setHeader("Name");
+        grid.addColumn(MessageHistory.Message::message).setHeader("Message");
+        grid.setItems(history.all());
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send, grid);
+    }
+
+    private void sendMessage() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        String nameError = name.getValue().isBlank() ? "Name is required" : null;
+        String emailError = null;
+        if (email.getValue().isBlank() && phone.getValue().isBlank()) {
+            emailError = "Give an e-mail address or a phone number";
+        } else if (!email.getValue().isBlank()
+                && new EmailValidator("Enter a valid e-mail address")
+                        .apply(email.getValue(), null).isError()) {
+            emailError = "Enter a valid e-mail address";
+        }
+        String messageError = message.getValue().isBlank() ? "Message is required"
+                : message.getValue().length() > 500 ? "Message must be at most 500 characters" : null;
+        name.setErrorMessage(nameError);
+        name.setInvalid(nameError != null);
+        email.setErrorMessage(emailError);
+        email.setInvalid(emailError != null);
+        message.setErrorMessage(messageError);
+        message.setInvalid(messageError != null);
+        if (nameError != null || emailError != null || messageError != null) {
+            return;
+        }
+        history.add(new MessageHistory.Message(name.getValue(), email.getValue(),
+                phone.getValue(), message.getValue()));
+        grid.setItems(history.all());
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty()) {
+            return;
+        }
+        var navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Paragraph("Your unsent message will be lost if you leave."));
+        dialog.getFooter().add(new Button("Keep editing", click -> {
+            navigation.cancel();
+            dialog.close();
+        }), new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        }));
+        dialog.open();
+    }
+}
