+package com.example;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.textfield.*;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    private TextField field(String label) { return $(TextField.class).withLabel(label).single(); }
+    private Button button(String text) { return $(Button.class).withText(text).single(); }
+
+    @Test
+    void validatesAndSendsWithEnterThenRetainsHistory() {
+        navigate(ContactView.class);
+        var send = button("Send");
+        var name = field("Name");
+        var phone = field("Phone");
+        var email = $(EmailField.class).single();
+        var message = $(TextArea.class).single();
+        int originalSize = $(Grid.class).single().getListDataView().getItemCount();
+        assertTrue(send.isEnabled());
+        test(send).click();
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(name.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertTrue(send.isEnabled());
+        test(name).setValue("Ada");
+        test(email).setValue("broken");
+        test(message).setValue("x".repeat(501));
+        test(send).click();
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(originalSize, $(Grid.class).single().getListDataView().getItemCount());
+        test(email).setValue("");
+        test(phone).setValue("123456");
+        test(message).setValue("Hello");
+        fireShortcut(Key.ENTER);
+        assertFalse(send.isEnabled());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty() && message.isEmpty());
+        assertEquals(originalSize + 1, $(Grid.class).single().getListDataView().getItemCount());
+        test($(RouterLink.class).single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+        assertEquals(originalSize + 1, $(Grid.class).single().getListDataView().getItemCount());
+        test(field("Name")).setValue("Grace");
+        test($(EmailField.class).single()).setValue("grace@example.com");
+        test($(TextArea.class).single()).setValue("Second");
+        test(button("Send")).click();
+        assertFalse(button("Send").isEnabled());
+        var latest = (MessageHistory.Message) $(Grid.class).single().getListDataView().getItem(0);
+        assertEquals("Second", latest.message());
+        test(field("Phone")).setValue("7");
+        assertTrue(button("Send").isEnabled());
+    }
+
+    @Test
+    void guardsLinkAndProgrammaticNavigation() {
+        navigate(ContactView.class);
+        test(field("Phone")).setValue("unsent");
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened());
+        test(button("Keep editing")).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("unsent", field("Phone").getValue());
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue($(Dialog.class).single().isOpened());
+        test(button("Discard")).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+    }
+}
